func TestParseMarkdownBasic(t *testing.T) {
	src := `# Attention Is All You Need
- Author: Ashish Vaswani, Noam Shazeer
- Tags: transformer, attention,  NLP
- Year: 2017

# Comment
The paper that started it all.

# Abstract (autogenerated)
The dominant sequence transduction models are based on complex
recurrent or convolutional neural networks.
`
	e, err := ParseMarkdown(src)
	if err != nil {
		t.Fatalf("ParseMarkdown: %v", err)
	}
	if e.Title != "Attention Is All You Need" {
		t.Errorf("Title = %q", e.Title)
	}
	if e.Author != "Ashish Vaswani, Noam Shazeer" {
		t.Errorf("Author = %q", e.Author)
	}
	if got := strings.Join(e.Tags, "|"); got != "transformer|attention|NLP" {
		t.Errorf("Tags = %q", got)
	}
	if e.FieldString("Year") != "2017" {
		t.Errorf("Year = %q", e.FieldString("Year"))
	}
	if e.Comment != "The paper that started it all." {
		t.Errorf("Comment = %q", e.Comment)
	}
	if !strings.Contains(e.Abstract, "dominant sequence transduction") {
		t.Errorf("Abstract = %q", e.Abstract)
	}
	if !strings.Contains(e.Abstract, "convolutional neural networks.") {
		t.Errorf("abstract lost its second line: %q", e.Abstract)
	}
	if e.Auto {
		t.Error("a hand-edited entry must not be marked automatic")
	}
}

func TestParseMarkdownTitleOnly(t *testing.T) {
	e, err := ParseMarkdown("# Just A Title\n")
	if err != nil {
		t.Fatalf("ParseMarkdown: %v", err)
	}
	if e.Title != "Just A Title" {
		t.Errorf("Title = %q", e.Title)
	}
	if e.Author != "" || len(e.Tags) != 0 || e.Abstract != "" {
		t.Errorf("unexpected extras: %+v", e)
	}
}

func TestParseMarkdownErrors(t *testing.T) {
	for _, src := range []string{"", "\n\n", "- Author: x\n", "#\n# Abstract\nabc\n"} {
		if _, err := ParseMarkdown(src); err != ErrNoTitle {
			t.Errorf("ParseMarkdown(%q) error = %v, want ErrNoTitle", src, err)
		}
	}
}

func TestParseMarkdownTolerates(t *testing.T) {
	// CRLF, extra bullets, bullet after a heading, "# author" heading form,
	// unknown sections.
	src := "# A Title\r\n- author:  Jane Doe \r\n- tag: a,b\r\n" +
		"# Venue\r\nNeurIPS\r\n"
	e, err := ParseMarkdown(src)
	if err != nil {
		t.Fatalf("ParseMarkdown: %v", err)
	}
	if e.Title != "A Title" {
		t.Errorf("Title = %q", e.Title)
	}
	if e.Author != "Jane Doe" {
		t.Errorf("Author = %q", e.Author)
	}
	if got := strings.Join(e.Tags, ","); got != "a,b" {
		t.Errorf("Tags = %q", got)
	}
	if e.FieldString("Venue") != "NeurIPS" {
		t.Errorf("Venue = %q", e.FieldString("Venue"))
	}
}

func TestMarkdownRoundTrip(t *testing.T) {
	orig := &Entry{
		Title:    "Round Trip",
		Author:   "A. Author",
		Tags:     []string{"x", "y"},
		Abstract: "An abstract that spans.\nTwo lines.",
		Comment:  "A comment.",
	}
	orig.SetField("DOI", "10.1234/abc")

	text := FormatMarkdown(orig)
	back, err := ParseMarkdown(text)
	if err != nil {
		t.Fatalf("ParseMarkdown: %v\n---\n%s", err, text)
	}
	if back.Title != orig.Title || back.Author != orig.Author ||
		strings.Join(back.Tags, ",") != strings.Join(orig.Tags, ",") {
		t.Errorf("round trip mismatch:\n got %+v\nwant %+v", back, orig)
	}
	if strings.TrimSpace(back.Abstract) != strings.TrimSpace(orig.Abstract) {
		t.Errorf("Abstract = %q, want %q", back.Abstract, orig.Abstract)
	}
	if back.Comment != orig.Comment {
		t.Errorf("Comment = %q, want %q", back.Comment, orig.Comment)
	}
	if back.FieldString("DOI") != "10.1234/abc" {
		t.Errorf("DOI = %q", back.FieldString("DOI"))
	}
}

func TestFormatMarkdownOrder(t *testing.T) {
	e := &Entry{Title: "T", Tags: []string{"b", "a"}}
	e.SetField("Year", "2020")
	e.SetField("Zeta", "z")
	out := FormatMarkdown(e)
	lines := strings.Split(out, "\n")
	if !strings.HasPrefix(lines[0], "# T") {
		t.Fatalf("first line = %q", lines[0])
	}
	if !strings.Contains(out, "- Author:") || !strings.Contains(out, "- Tags: b, a") {
		t.Errorf("missing standard bullets:\n%s", out)
	}
	// Known fields (Year) sort before unknown ones (Zeta).
	yi, zi := strings.Index(out, "- Year:"), strings.Index(out, "- Zeta:")
	if yi < 0 || zi < 0 || yi > zi {
		t.Errorf("field order wrong (year=%d zeta=%d):\n%s", yi, zi, out)
	}
}

