func TestStoreRoundTrip(t *testing.T) {
	dir := t.TempDir()
	s, err := Load(dir)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if err := s.Config.AddTool(Tool{Name: "firefox", Command: "firefox", Type: ToolGUI}); err != nil {
		t.Fatal(err)
	}
	e := &Entry{Title: "Stored", Author: "Someone", Tags: []string{"t1"}, Auto: true}
	e.SetField("custom", "value")
	s.Set("a.pdf", e)
	if err := s.Save(); err != nil {
		t.Fatalf("Save: %v", err)
	}

	again, err := Load(dir)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	got, ok := again.Lookup("a.pdf")
	if !ok {
		t.Fatal("entry missing after reload")
	}
	if got.Title != "Stored" || got.Author != "Someone" || !got.Auto {
		t.Errorf("entry = %+v", got)
	}
	if got.FieldString("custom") != "value" {
		t.Errorf("custom field lost: %+v", got.Fields)
	}
	if got := again.Config.Tools[0].Command; got != "firefox" {
		t.Errorf("config lost: %q", got)
	}
	if again.Config.DefaultTool != "firefox" {
		t.Errorf("default tool = %q", again.Config.DefaultTool)
	}
}

func TestStoreExtensibleFields(t *testing.T) {
	// Unknown keys written by another tool must survive a load/save cycle.
	dir := t.TempDir()
	raw := `{
	  "version": 1,
	  "entries": {
	    "x.pdf": {
	      "title": "T",
	      "doi": "10.1/x",
	      "citations": 42,
	      "extra": {"nested": true}
	    }
	  }
	}`
	if err := os.WriteFile(filepath.Join(dir, StoreFile), []byte(raw), 0o644); err != nil {
		t.Fatal(err)
	}
	s, err := Load(dir)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	e, _ := s.Lookup("x.pdf")
	if e.FieldString("doi") != "10.1/x" {
		t.Errorf("doi = %q", e.FieldString("doi"))
	}
	if err := s.Save(); err != nil {
		t.Fatal(err)
	}
	var decoded map[string]any
	b, err := os.ReadFile(filepath.Join(dir, StoreFile))
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(b, &decoded); err != nil {
		t.Fatal(err)
	}
	ent := decoded["entries"].(map[string]any)["x.pdf"].(map[string]any)
	if ent["citations"] != float64(42) {
		t.Errorf("citations lost: %v", ent["citations"])
	}
	if _, ok := ent["extra"].(map[string]any); !ok {
		t.Errorf("nested extra field lost: %v", ent["extra"])
	}
}

func TestStoreRenameDeletePrune(t *testing.T) {
	dir := t.TempDir()
	for _, n := range []string{"keep.pdf", "gone.pdf"} {
		if err := os.WriteFile(filepath.Join(dir, n), []byte("%PDF-1.4"), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	s := New()
	s.path = filepath.Join(dir, StoreFile)
	s.Set("keep.pdf", &Entry{Title: "Keep"})
	s.Set("gone.pdf", &Entry{Title: "Gone"})

	if err := os.Rename(filepath.Join(dir, "keep.pdf"), filepath.Join(dir, "renamed.pdf")); err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(filepath.Join(dir, "gone.pdf")); err != nil {
		t.Fatal(err)
	}
	s.Rename("keep.pdf", "renamed.pdf")
	if _, ok := s.Lookup("keep.pdf"); ok {
		t.Error("old name still present after Rename")
	}
	if e, ok := s.Lookup("renamed.pdf"); !ok || e.Title != "Keep" {
		t.Error("Rename did not move the entry")
	}

	removed := s.Prune(dir)
	if len(removed) != 1 || removed[0] != "gone.pdf" {
		t.Errorf("Prune removed %v, want [gone.pdf]", removed)
	}
	if _, ok := s.Lookup("gone.pdf"); ok {
		t.Error("pruned entry still present")
	}
}

func TestStoreEmptyFile(t *testing.T) {
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, StoreFile), nil, 0o644); err != nil {
		t.Fatal(err)
	}
	s, err := Load(dir)
	if err != nil {
		t.Fatalf("Load of empty file: %v", err)
	}
	if len(s.Entries) != 0 {
		t.Errorf("entries = %v", s.Entries)
	}
}

func TestStoreCorruptFile(t *testing.T) {
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, StoreFile), []byte("{not json"), 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := Load(dir); err == nil {
		t.Fatal("Load of corrupt file should fail")
	}
}

func TestEntryAuthorArray(t *testing.T) {
	// Tolerate "author" given as a list, as other tools do.
	e := &Entry{}
	if err := json.Unmarshal([]byte(`{"title":"T","author":["A","B"]}`), e); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	if e.Author != "A, B" {
		t.Errorf("Author = %q", e.Author)
	}
}
